import csv
import io
import re
from typing import List, Dict, Any, Optional

def parse_csv(raw_csv: str):
    if raw_csv is None:
        return {"columns": [], "rows": []}

    text = raw_csv.replace("\r\n", "\n").replace("\r", "\n")
    lines = text.split("\n")

    def is_preamble_line(s: str) -> bool:
        t = s.strip()
        if not t:
            return True
        if re.match(r'^\s*Source\s*:', t, re.IGNORECASE):
            return True
        return False

    def split_physical_lines(all_lines: List[str]) -> List[str]:
        return all_lines

    physical_lines = split_physical_lines(lines)

    def parse_record_stream(all_lines: List[str]) -> List[List[str]]:
        records = []
        buf = []
        in_quotes = False

        for line in all_lines:
            if not buf and is_preamble_line(line):
                continue
            buf.append(line)
            i = 0
            while i < len(line):
                ch = line[i]
                if ch == '"':
                    if in_quotes and i + 1 < len(line) and line[i + 1] == '"':
                        i += 1
                    else:
                        in_quotes = not in_quotes
                i += 1
            if not in_quotes:
                record_text = "\n".join(buf)
                buf = []
                if record_text.strip() == "":
                    continue
                reader = csv.reader(io.StringIO(record_text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
                try:
                    row = next(reader)
                except StopIteration:
                    continue
                records.append([str(v) for v in row])

        if buf:
            record_text = "\n".join(buf)
            if record_text.strip():
                reader = csv.reader(io.StringIO(record_text), delimiter=",", quotechar='"', doublequote=True, skipinitialspace=False)
                try:
                    row = next(reader)
                    records.append([str(v) for v in row])
                except StopIteration:
                    pass
        return records

    rows = parse_record_stream(physical_lines)

    if not rows:
        return {"columns": [], "rows": []}

    header_rows = 3
    if len(rows) >= header_rows:
        header_parts = rows[:header_rows]
        max_len = max(len(r) for r in header_parts)
        columns = []
        for i in range(max_len):
            parts = []
            for r in header_parts:
                parts.append(r[i] if i < len(r) else "")
            name = " ".join([p.strip() for p in parts if p.strip() != ""]).strip()
            columns.append(name)
        data_rows = rows[header_rows:]
        normalized_rows = []
        for r in data_rows:
            if len(r) < len(columns):
                r = r + [""] * (len(columns) - len(r))
            elif len(r) > len(columns):
                r = r[:len(columns)-1] + [",".join(r[len(columns)-1:])]
            normalized_rows.append([str(v) for v in r])
        return {"columns": columns, "rows": normalized_rows}

    columns = rows[0]
    data_rows = rows[1:]
    normalized_rows = []
    for r in data_rows:
        if len(r) < len(columns):
            r = r + [""] * (len(columns) - len(r))
        elif len(r) > len(columns):
            r = r[:len(columns)-1] + [",".join(r[len(columns)-1:])]
        normalized_rows.append([str(v) for v in r])
    return {"columns": columns, "rows": normalized_rows}
